else if (st==='noir'){ strut=[210,6,72]; rimC=[210,4,90]; spokeC=[210,5,50]; }
else if (st==='chrome'){ strut=[210,20,80]; rimC=[280,30,95]; spokeC=[180,25,85]; }
else { strut=[28,55,72]; rimC=[H,45,88]; spokeC=[35,40,66]; }
// ---- support A-frame legs to ground ----
