push();
if (wire){ stroke(strut[0],strut[1],strut[2],80); strokeWeight(Math.max(1,u*0.003)); noFill(); }
else { stroke(strut[0],strut[1],strut[2]*0.7,100); strokeWeight(Math.max(2,u*0.012)); }
line(cxp, cyp, cxp - R*0.55, groundY);
line(cxp, cyp, cxp + R*0.55, groundY);
