push();
translate(cxp, cyp);
// rim ring
noFill();
if (st==='neon'){ drawingContext.shadowColor=color(rimC[0],rimC[1],100,90).toString(); drawingContext.shadowBlur=u*0.03*(0.5+P.energy); }
stroke(rimC[0], rimC[1], rimC[2], wire?70:100); strokeWeight(wire?Math.max(1,u*0.003):Math.max(2,u*0.01));
ellipse(0,0,R*2,R*2);
if (st!=='neon'){} else { drawingContext.shadowBlur=0; }
ellipse(0,0,R*1.86,R*1.86);
// spokes
stroke(spokeC[0], spokeC[1], spokeC[2], wire?60:90); strokeWeight(wire?Math.max(1,u*0.0025):Math.max(1.5,u*0.006));
